void CMemo2DLayout::main() {
    D2::C2DSeqCtrl* pSeq;
    switch (getState()) {
    case 0:
        break;
    case 1:
        createLayer(0);
        initialize();
        setState(2);
        break;
    case 2:
        if (isEndLayer()) {
            destroyLayer();
            createLayer(1);
            setStateFlag(4, 0);
            setState(3);
        }
        break;
    case 3:
        break;
    case 4:
        destroyLayer();
        createLayer(2);
        setState(5);
        break;
    case 5:
        if (isEndLayer()) {
            destroyLayer();
            setStateFlag(0x10, 0);
            setState(6);
        }
        break;
    case 6:
        break;
    case 7:
        out();
        break;
    default:
        out();
        break;
    }
    for (INT i = 0; i < m_iSeqNum; i++) {
        pSeq = getSeqCtrl(i);
        if (pSeq && pSeq->isEnableDisp() && m_pSeqCodeTbl) {
            if (m_pSeqCodeTbl[i] == m_pSeqNoTbl[i].In && pSeq->isEnd(0)) {
                setSeqState(i, 1);
            } else if (m_pSeqCodeTbl[i] == m_pSeqNoTbl[i].Out && pSeq->isEnd(0)) {
                setSeqState(i, -1);
            }
        }
    }
}
